"""Plain text absence notices for parents."""

from datetime import date
from typing import Iterable, List

from rosterkit.attendance import days_missed
from rosterkit.models import Mark, Student

def format_day(day: date) -> str:
    """Spell a day out, e.g. September 3, 2026."""
    return f"{day:%B} {day.day}, {day.year}"

def check_owner(
    student: Student, marks: List[Mark]
) -> None:
    """Refuse marks that belong to someone else."""
    ids = {mark.student_id for mark in marks}
    other = ids - {student.student_id}
    if other:
        names = ", ".join(sorted(other))
        raise ValueError(f"other students: {names}")

def absent_days(
    student: Student, marks: List[Mark]
) -> List[date]:
    """Distinct absent days, oldest first."""
    check_owner(student, marks)
    days = sorted(set(days_missed(marks)))
    if not days:
        raise ValueError("no absences to report")
    return days

def absence_notice(
    student: Student, marks: Iterable[Mark]
) -> str:
    """Build a short notice of the days a student missed."""
    days = absent_days(student, list(marks))
    name = f"{student.first_name} {student.last_name}"
    when = "\n".join(f"- {format_day(d)}" for d in days)
    unit = "day" if len(days) == 1 else "days"
    return f"{name} missed {len(days)} {unit}:\n{when}"
